const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function heat(dish, ms) {
  console.log(dish + " in");
  await delay(ms);
  console.log(dish + " out");
  return dish;
}

async function serve() {
  const pie = heat("pie", 40);
  const soup = heat("soup", 10);
  console.log(await pie);
  console.log(await soup);
}

serve();
